<div class="grid gap-6 md:grid-cols-2"><x-form.input name="title" label="Title" :value="old('title', $slide->title)" required /><x-form.input name="subtitle" label="Subtitle" :value="old('subtitle', $slide->subtitle)" /><x-form.input name="link_url" label="Link URL" :value="old('link_url', $slide->link_url)" /><x-form.input name="sort_order" type="number" label="Sort order" :value="old('sort_order', $slide->sort_order ?? 0)" /><x-form.select name="status" label="Status"><option value="draft" @selected(old('status', $slide->status?->value ?? 'draft') === 'draft')>Draft</option><option value="published" @selected(old('status', $slide->status?->value ?? 'draft') === 'published')>Published</option></x-form.select><x-form.file-upload name="image" label="Image" upload-profile="images.homepage_slide" :required="!$slide->exists" /></div><div class="flex justify-end"><button class="rounded-lg bg-brand-500 px-5 py-3 text-sm font-medium text-white">{{ $submitLabel }}</button></div>
